// Generated by Trae Work
(function() {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();
  var emerald = '#10b981';
  var amber = '#f59e0b';
  var purple = '#a78bfa';

  var chart1 = echarts.init(document.getElementById('chart-gantt'), null, { renderer: 'svg' });

  // Gantt chart: horizontal bar showing task duration
  var tasks = [
    { name: '1. 场景化入口', category: 'P0 交易平台', start: 0, end: 3, color: emerald },
    { name: '2. 双维度筛选', category: 'P0 交易平台', start: 0, end: 2, color: emerald },
    { name: '3. 模型分类标签', category: 'P0 交易平台', start: 1, end: 3, color: emerald },
    { name: '4. 模型管理分类字段', category: 'P0 银行平台', start: 0, end: 4, color: emerald },
    { name: '5. 鉴权方扩展', category: 'P1 银行平台', start: 4, end: 6, color: amber },
    { name: '7. 数据维度扩展', category: 'P1 用户平台', start: 4, end: 7, color: amber },
    { name: '8. 训练存款产品', category: 'P1 用户平台', start: 5, end: 7, color: amber },
    { name: '6. 训练存款产品配置', category: 'P2 银行平台', start: 7, end: 10, color: purple }
  ];

  var categories = [];
  tasks.forEach(function(t) {
    if (categories.indexOf(t.category) === -1) categories.push(t.category);
  });

  chart1.setOption({
    animation: false,
    tooltip: {
      trigger: 'item',
      appendToBody: true,
      formatter: function(p) {
        return p.name + '<br/>时间段: 第' + (p.value[1] + 1) + '-第' + (p.value[2]) + '周';
      }
    },
    grid: { left: '25%', right: '4%', top: '5%', bottom: '5%', containLabel: true },
    xAxis: {
      type: 'value',
      min: 0,
      max: 10,
      interval: 1,
      name: '周数',
      nameTextStyle: { color: muted },
      axisLabel: { color: muted, formatter: '第{v}周' },
      splitLine: { lineStyle: { color: rule } },
      axisLine: { lineStyle: { color: rule } }
    },
    yAxis: {
      type: 'category',
      data: tasks.map(function(t) { return t.name; }),
      axisLabel: { color: ink, fontSize: 11 },
      axisLine: { lineStyle: { color: rule } },
      axisTick: { show: false },
      splitArea: { show: false }
    },
    series: [{
      type: 'bar',
      data: tasks.map(function(t) { return { name: t.name, value: [t.start, t.end, t.category], itemStyle: { color: t.color } }; }),
      barWidth: '55%',
      label: {
        show: true,
        position: 'right',
        formatter: function(p) {
          var weeks = p.value[2] - p.value[1];
          return weeks + '周';
        },
        fontSize: 10,
        color: muted
      },
      encode: { x: [0, 1], y: 3 },
      barCategoryGap: '30%'
    }]
  });
  window.addEventListener('resize', function() { chart1.resize(); });
})();